<script lang="ts">
 import {page} from '$app/stores';import {goto} from '$app/navigation';import Heading from '$lib/components/Heading.svelte';import PasswordField from '$lib/components/database/PasswordField.svelte';import Credentials from '$lib/components/database/Credentials.svelte';import PrivilegeEditor from '$lib/components/database/PrivilegeEditor.svelte';import {databaseState,command,validatePassword} from '$lib/database/store';import {privilegeLabel,permissions,type HostMode} from '$lib/database/model';
 let error='',edit='',grant='',address='',mode:HostMode='Private remote network',password='',rotatedPassword='',confirmDelete='';
 $: id=$page.params.id||'';$: user=$databaseState.users.find(u=>u.id===id);$: databases=$databaseState.databases.filter(d=>user&&Object.prototype.hasOwnProperty.call(user.grants,d.id));$: available=$databaseState.databases.filter(d=>user&&d.engine===user.engine&&!Object.prototype.hasOwnProperty.call(user.grants,d.id));
 function run(fn:()=>void){try{error='';fn();}catch(e){error=e instanceof Error?e.message:'Action failed.';}}
</script>
{#if user}<Heading title={user.name} subtitle={user.engine+' · Database user'}><a class="btn secondary" href="/databases">Manage Databases</a><a class="btn secondary" href="/databases/users">Manage Users</a></Heading><div class="stack">{#if error}<p class="error" role="alert">{error}</p>{/if}<section class="card stack"><h3>Database access</h3>{#each databases as d}<div class="setting-row"><div><a class="link-btn" href={'/databases/'+d.id}>{d.name}</a><small style="display:block">{privilegeLabel(user.engine,user.grants[d.id])}</small></div><div class="row wrap"><button class="btn secondary small" on:click={()=>edit=edit===d.id?'':d.id}>Privileges</button><button class="btn danger small" on:click={()=>{if(window.confirm('Revoke access to '+d.name+'?'))run(()=>command({type:'revoke',database:d.id,user:id}));}}>Revoke</button></div></div>{#if edit===d.id}{#key d.id}<PrivilegeEditor engine={user.engine} initial={user.grants[d.id]} onSave={(values)=>{command({type:'grant',database:d.id,user:id,privileges:values});edit='';}} onCancel={()=>edit=''}/>{/key}{/if}{:else}<p class="subtitle">No databases assigned.</p>{/each}<form class="native-inline" on:submit|preventDefault={()=>run(()=>{if(!user)return;command({type:'grant',database:grant,user:id,privileges:permissions(user.engine)});grant='';})}><label class="field grow">Grant access to database<select bind:value={grant} required><option value="">Select database</option>{#each available as d}<option value={d.id}>{d.name}</option>{/each}</select></label><button class="btn primary" type="submit" disabled={!grant}>Grant full access</button></form></section>
<section class="card stack"><div><h3>Allowed hosts</h3><p class="subtitle">Same-server access is the default. Additional remote hosts are explicit, restricted demo rules.</p></div><div class="setting-row"><span>Same server only</span><small>Internal network · default</small></div>{#each user.hosts as h}<div class="setting-row"><div><strong>{h.address}</strong><small style="display:block">{h.mode}</small></div><button class="btn danger small" on:click={()=>run(()=>command({type:'host-remove',user:id,mode:h.mode,address:h.address}))}>Remove</button></div>{/each}<form class="stack" on:submit|preventDefault={()=>run(()=>{command({type:'host-add',user:id,mode,address});address='';})}><div class="db13-form-grid"><label class="field">Connection method<select bind:value={mode}><option>Private remote network</option><option>Restricted public TLS</option></select></label><label class="field">Allowed address<input bind:value={address} required placeholder="198.51.100.10"/></label></div><small>Specific IPv4 or /24–/32 CIDR only. Public access requires TLS in production. No firewall rules are modified.</small><div><button class="btn primary" type="submit">Add allowed host</button></div></form></section>
<form class="card stack" on:submit|preventDefault={()=>run(()=>{validatePassword(password);command({type:'rotate',user:id});rotatedPassword=password;password='';})}><h3>Change password</h3><PasswordField bind:value={password} inputId="rotate-password"/><small>Update connected applications after a real password change. This is a simulation.</small><div><button class="btn primary" type="submit">Change password</button></div></form>{#if rotatedPassword}<Credentials username={user.name} password={rotatedPassword} onClose={()=>rotatedPassword=''}/>{/if}<section class="card stack"><h3>Delete user</h3><p class="subtitle">This removes its sample access grants from every database.</p><label class="field">Type {user.name} to confirm<input bind:value={confirmDelete}/></label><div><button class="btn danger" disabled={confirmDelete!==user.name} on:click={()=>run(()=>{command({type:'delete-user',user:id});void goto('/databases/users');})}>Delete sample user</button></div></section></div>{:else}<Heading title="User not found" subtitle="This user is not in your workspace."/><a class="btn secondary" href="/databases/users">Manage Users</a>{/if}
